        severity: "error",
        plugin: `canonical/${dirName}`,
        file: v.file,
        line: v.line,
        message: `${v.file}:${v.line}: disallowed third-party MCP reference "${v.ref}" in canonical handler \u2014 view tools must not call source MCPs directly (P9 \xA72.7).`
